  $$('#egObj [data-v]').forEach(x => x.setAttribute('aria-pressed', String(x.dataset.v === EG.obj))); $('#egObj').hidden = $('#egObjL').hidden = EG.goal !== 'churn';
  $('#egPlan').innerHTML = egPlanHtml();
