    const tl = T.closest('[data-sutbl]'); if (tl) { SU.q = suTables()[tl.dataset.sutbl].zone === 'Restricted' ? `SELECT COUNT(*) AS n FROM ${tl.dataset.sutbl}` : `SELECT * FROM ${tl.dataset.sutbl} LIMIT 20`; suRunQuery(); return; }
