      link(r === 'grp' ? target : N.id, r === 'grp' ? N.id : target, r, { pct: r === 'grp' ? '' : pct, ex, uv, asset: asset || undefined, buyer: buyer || undefined, src, from, note: raw !== N.n ? raw + (group && h.pct ? ` (together ${kgPct(h.pct)})` : '') : '' });
