    g = kgSplit(g, /;/)[0]; if (/:/.test(kgOuter(g))) g = g.slice(g.indexOf(':') + 1);
    g = kgSplit(g, /\s[-–]\s|,\s+now\b/)[0].replace(/-controlled\b|\s+(is|has|largest)\b.*$|\s*~?\d+(\.\d+)?%\s*$/gi, '').replace(/^\d+\/\d+\s+JV\s+/i, '').trim();
