    const inv = kgOuter(d.investor), withs = kgParens(d.investor).filter(p => /^with\s/i.test(p)).flatMap(p => kgSplit(p.replace(/^with\s+/i, '').replace(/\s*~?\d+%.*$/, ''), /,\s*/));
