  const geoRe = KG_GEO.map(r => [r[0], r.map(n => /^[A-Z]{2,4}$/.test(n) ? [n, new RegExp(`(^|[^A-Za-z])${n}([^A-Za-z]|$)`), false] : [kgFold(n), new RegExp(`(^|[^a-z])${kgFold(n).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^a-z]|$)`), true])]);
