  const local = (id, k, ctx) => { const loc = (opsIn.get(ctx) || []).filter(x => kgKey(G.N.get(x).n).startsWith(k + ' ')).sort((x, y) => +kgKey(G.N.get(y).n).endsWith(kgKey(ctx)) - +kgKey(G.N.get(x).n).endsWith(kgKey(ctx)))[0]; return loc || id; };
