  $$(`#kgL${k} [role="option"]`).forEach((li, i) => li.setAttribute('aria-selected', String(i === S.i)));
  $(`[data-kgsug="${k}"]`).setAttribute('aria-activedescendant', `kgO${k}${S.i}`); const li = $(`#kgO${k}${S.i}`); if (li) li.scrollIntoView({ block: 'nearest' });
