    entities: G.list.map(N => ({ id: N.id, name: N.n, type: KG_T[N.t][0], kind: N.k ? KG_INV[N.k] : undefined, also_written: [...N.aka].filter(a => a !== N.n), connections: N.deg, pagerank: +N.pr.toFixed(6), sources: N.src })),
