    const t = Array.isArray(v) ? 'array' : v === null ? 'null' : typeof v, ok = !p.type || (p.type === 'integer' ? Number.isInteger(v) : p.type === 'number' ? typeof v === 'number' && isFinite(v) : p.type === t);
